-- Temple of Ahn'Qiraj: the Classic armor, jewelry, cloaks, shields and off-hands that drop there had no item row
-- (the WoW Forever client blanks them), so every one was an invalid loot item and nothing dropped. Rows from the
-- Classic item data: stats as budget shares, armor from the item level formula, Classic sell prices, Classic
-- equip and use spells as item effects, hotfix_data so the client shows them.
DELETE FROM `item_sparse` WHERE `ID` IN (21599,21617,21621,21626,21627,21651,21652,21666,21668,21671,21675,21676,21680,21682,21683,21684,21686,21688,21689,21691,21692,21696,21697,21698,21699,21701,21704,21705,21706,21708,21814,21838,21889,22730,22731);
DELETE FROM `item_effect` WHERE `ID` BETWEEN 9900639 AND 9900677;
DELETE FROM `item_x_item_effect` WHERE `ID` BETWEEN 9900639 AND 9900677;
DELETE FROM `hotfix_data` WHERE `Id` BETWEEN 26113108 AND 26113220;
